class Solution:
    def binaryGap(self, n: int) -> int:
        max_gap = 0
        current_gap = 0
        found_one = False

        while n > 0:
            bit = n % 2
            if bit == 1:
                if found_one:
                    max_gap = max(max_gap, current_gap))
                else:
                    found_one = True
                current_gap = 0
            else:
                if found_one:
                    current_gap += 1
            n //= 2

        return max_gap

