class Solution:
    def findNthDigit(self, n: int) -> int:
        if n < 10:
            return n
        digits = 1
        while n > digits * 9 * 10**(digits-1)):
            n -= digits * 9 * 10**(digits-1))
            digits += 1
        num = 10**(digits-1)) + (n - 1) // digits
        return int(str(num)[(n - 1) % digits)]

class Solution:
    def findNthDigit(self, n: int) -> int:
        if n < 10:
            return n
        digits = 1
        while True:
            first_digit = 1 if digits == 1 else 10**(digits - 1)
            last_digit = first_digit + 9 * (10 ** (digits - 1))))
            if n >= first_digit and n <= last_digit:
                break
            digits += 1
        offset = n - first_digit
        return int(str(first_digit + offset // digits))[offset % digits])

